+/* Editorial finish: resilient controls, calmer surfaces, and safe mobile spacing. */
+html{min-height:100%;scrollbar-gutter:stable}
+body{min-height:100svh;background-attachment:fixed}
+::selection{background:rgba(177,218,98,.38);color:#183821}
+button,select,input{accent-color:#78a341}
+button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #789c45;outline-offset:3px}
+button:not(:disabled){touch-action:manipulation}
+.panel,.party-bar,.phase-card,.stats-panel,.clue-card{backdrop-filter:saturate(1.02)}
+.panel-heading h2,.settings-title,.phase-card h1,.stats-wrap .phase-head h1{ text-wrap:balance }
+.phase-description,.hero-copy{ text-wrap:pretty }
+.text-input,.party-select,.modal-card textarea{box-shadow:inset 0 1px 2px rgba(27,48,33,.025)}
+.player-row:focus-within{border-color:#a9c27b;background:#fbfcf7}
+.row-action:focus-visible,.mini-link:focus-visible,.text-btn:focus-visible{border-radius:7px}
+.switch:focus-visible{outline-offset:4px}
+.vote-option:disabled{opacity:.55}
+.result-banner,.verbal-instruction{box-shadow:inset 3px 0 0 rgba(120,163,65,.4)}
+.result-banner.bad{box-shadow:inset 3px 0 0 rgba(190,96,72,.48)}
+.pack-modal{background:rgba(24,38,29,.56);backdrop-filter:blur(5px);padding:max(20px,env(safe-area-inset-top)) max(20px,env(safe-area-inset-right)) max(20px,env(safe-area-inset-bottom)) max(20px,env(safe-area-inset-left))}
+.modal-card{max-height:min(90svh,720px);overflow:auto;box-shadow:0 24px 80px rgba(17,35,23,.22)}
+.toast{bottom:max(25px,calc(env(safe-area-inset-bottom) + 12px));max-width:calc(100vw - 32px);text-align:center}

